import { Stack } from '@absoluteui/components/layout';

const list = document.createElement('div');
document.body.append(list);
const stack = Stack.apply(list, { gap: 6 });
stack.update({ align: 'start' });

import { Container, Grid } from '@absoluteui/components/layout';

const page = document.createElement('main');
const tiles = document.createElement('div');
page.append(tiles);
document.body.append(page);
Container.apply(page, { size: 'xl' });
const grid = Grid.apply(tiles, { minColumnWidth: '14rem', gap: 4 });
// Later, when the view is removed:
grid.destroy();

import { Divider, Flex } from '@absoluteui/components/layout';
import { Button } from '@absoluteui/components/button';

const toolbar = document.createElement('div');
const save = document.createElement('button');
save.textContent = 'Save';
Button.enhance(save);
const share = document.createElement('button');
share.textContent = 'Share';
Button.enhance(share);
toolbar.append(save, Divider.create({ orientation: 'vertical' }), share);
document.body.append(toolbar);
Flex.apply(toolbar, { gap: 2, align: 'center', justify: 'end' });
